#include <base/subtle/atomic32.h>

bool FinalizeAsyncPixelTransfer(base::subtle::Atomic32 submit_count) {
    // Retrieve shared memory buffer
    void* shared_memory = GetSharedMemoryBuffer();
    if (!shared_memory) {
        return false;
    }

    // Setup memory parameters for pixel transfer
    PixelTransferParams params;
    if (!SetupMemoryParams(shared_memory, &params)) {
        return false;
    }

    // Create observer for completion notifications
    CompletionObserver* observer = CreateCompletionObserver();
    if (!observer) {
        return false;
    }

    // Request AsyncPixelTransferManager to notify when done
    AsyncPixelTransferManager* manager = GetAsyncPixelTransferManager();
    if (!manager) {
        return false;
    }

    if (!manager->RequestCompletionNotification(observer)) {
        return false;
    }

    // Add operation to pending transfer queue
    return manager->AddPendingTransfer(submit_count, params);
}

